const request = require('request');

const options = {
  method: 'POST',
  url: 'http://localhost:7000/rest/v2.1/companies/%7Bcompany_id%7D/uploads',
  headers: {'content-type': 'application/json'},
  body: {
    file_name: 'string',
    file_size: 1,
    content_type: 'string',
    sha256: 'string',
    md5: 'string',
    url_expires_in: 60,
    segments: [{size: 1, sha256: 'string', md5: 'string'}],
    uploader_tool_name: 'certifications',
    analytics: {
      application: {
        procore_os_name: 'iOS',
        procore_app_version: '23.1.0',
        client_sdk_name: 'procore-file-select',
        client_sdk_version: 'string'
      },
      network: {network_type: 'wifi', network_info: {property1: null, property2: null}},
      device: {
        device_type: 'mobile',
        device_model: 'iPhone 14 Pro',
        device_manufacturer: 'Apple',
        screen_resolution: '1920x1080',
        browser_name: 'Chrome',
        browser_version: 'string'
      }
    },
    custom_metadata: {property1: 'string', property2: 'string'}
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("http://localhost:7000/rest/v2.1/companies/%7Bcompany_id%7D/uploads"),
    Content = new StringContent("{\"file_name\":\"string\",\"file_size\":1,\"content_type\":\"string\",\"sha256\":\"string\",\"md5\":\"string\",\"url_expires_in\":60,\"segments\":[{\"size\":1,\"sha256\":\"string\",\"md5\":\"string\"}],\"uploader_tool_name\":\"certifications\",\"analytics\":{\"application\":{\"procore_os_name\":\"iOS\",\"procore_app_version\":\"23.1.0\",\"client_sdk_name\":\"procore-file-select\",\"client_sdk_version\":\"string\"},\"network\":{\"network_type\":\"wifi\",\"network_info\":{\"property1\":null,\"property2\":null}},\"device\":{\"device_type\":\"mobile\",\"device_model\":\"iPhone 14 Pro\",\"device_manufacturer\":\"Apple\",\"screen_resolution\":\"1920x1080\",\"browser_name\":\"Chrome\",\"browser_version\":\"string\"}},\"custom_metadata\":{\"property1\":\"string\",\"property2\":\"string\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

